import { isFunction, round } from 'lodash-es';
import React, { useMemo } from 'react';
import styled from 'styled-components';

import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { useChartInnerElement } from '../../context/InnerElementContext.js';
import { buildCumulativeValues } from '../../functions/build-cumulative-value.js';

interface InnerWrapperProps {
  width: number;
  height: number;
  innerRadius: number;
  visibleIds: string[];
}

const InnerContainer = /* @__PURE__ */ styled(Flex)<{
  $width: number;
  $height: number;
  $donutInner: number;
}>(({ $width, $height, $donutInner }) => ({
  position: 'absolute',
  top: `${$height / 2 - $donutInner / 2}px`,
  left: `${$width / 2 - $donutInner / 2}px`,
  justifyContent: 'center',
  alignItems: 'center',
}));

const InnerDonut = /* @__PURE__ */ styled(Flex)<{
  $donutInner: number;
}>(({ $donutInner }) => ({
  width: `${$donutInner}px`,
  height: `${$donutInner}px`,
  justifyContent: 'center',
  alignItems: 'center',
  overflow: 'hidden',
}));

export const InnerWrapper = ({
  width,
  height,
  innerRadius,
  visibleIds,
}: InnerWrapperProps) => {
  const { innerElement, originalData } = useChartInnerElement();

  // Formula to calculate the maximum square inside a circle =  √2 × radius
  const donutInner = Math.sqrt(2) * innerRadius;

  const { absoluteValue, relativeValue } = useMemo(
    () => buildCumulativeValues(originalData, visibleIds),
    [visibleIds, originalData],
  );

  if (!innerElement) {
    return null;
  }

  return (
    <InnerContainer $width={width} $height={height} $donutInner={donutInner}>
      <InnerDonut $donutInner={donutInner}>
        {isFunction(innerElement)
          ? innerElement({
              absoluteValue,
              relativeValue: round(relativeValue, 2),
              dimensions: { width: donutInner, height: donutInner },
            })
          : innerElement}
      </InnerDonut>
    </InnerContainer>
  );
};
